    45	      chart: {
    46	        size: {adaptive: true, resizeDebounceMs: 50},
    47	        select: {zoom: true},
    48	      },
    49	      cursor: {x: {visible: true}, y: {visible: true}},
    50	      tooltip: {show: true, tracking: 'sticky'},
    51	      scales: {y: {range: () => [0, 100]}},
    52	      appearance: {theme},
    53	    });
    54	    chartRef.current = chart;
    55	
    56	    // Append one sample each second and trim the same number from the start.
    57	    // Yagr's incremental splice path keeps the rolling 24-hour window without
    58	    // rebuilding the full 86,400-point series on every update.
    59	    const timer = window.setInterval(() => {
    60	      const timestamp = Date.now();
    61	      chart.setSeries(
    62	        [timestamp],
    63	        [{id: SERIES_ID, data: [getCpuValue(timestamp)]}],
    64	        {incremental: true, splice: true},
    65	      );
    66	    }, 1000);
    67	
    68	    return () => {
    69	      window.clearInterval(timer);
    70	      chart.dispose();
    71	      chartRef.current = undefined;
    72	    };
    73	  }, []);
    74	
    75	  useEffect(() => {
    76	    chartRef.current?.setTheme(theme);
    77	  }, [theme]);
    78	
    79	  return (
    80	    <main className="monitor-page">
    81	      <header className="monitor-header">
    82	        <div>
    83	          <p className="monitor-eyebrow">МОНИТОРИНГ СИСТЕМЫ</p>
    84	          <h1>Загрузка CPU</h1>
    85	          <p className="monitor-subtitle">Использование процессора за последние 24 часа</p>
    86	        </div>
    87	        <div className="live-indicator" aria-label="Данные обновляются в реальном времени">
    88	          <span className="live-dot" />
    89	          <span>В реальном времени</span>
    90	        </div>
    91	      </header>
    92	
    93	      <section className="chart-card" aria-label="Интерактивный график загрузки CPU">
    94	        <div className="chart-meta">
    95	          <div>
    96	            <span className="chart-label">CPU</span>
    97	            <span className="chart-unit">% использования</span>
    98	          </div>
    99	          <span className="chart-hint">Наведите для деталей · выделите область, чтобы приблизить</span>
   100	        </div>
   101	        <div className="chart-host" ref={hostRef} />
   102	        <div className="time-range" aria-hidden="true">
   103	          <span>24 часа назад</span>
   104	          <span>Сейчас</span>
   105	        </div>
   106	      </section>
   107	    </main>
   108	  );
   109	}
